// ============================================================================
// AETHER ENGINE SOURCE — the verified engine notebook, stored as a TEMPLATE
//
// WHY THIS FILE EXISTS (root cause 2026-09-03):
//   Pulling kernel source from Kaggle is structurally unreliable:
//     - deleted kernels cannot be pulled at all (account A: 404/500 on GetKernel)
//     - private kernels can ONLY be pulled by their own owner's token
//       (cross-account pull = 403 Forbidden — proven live both ways)
//   So the wake path must NOT fetch source from Kaggle. It embeds the verified
//   notebook here instead, verifies its integrity at runtime against the pinned
//   SHA-256 below, and refuses to push anything else.
//
// FIX (audit C3/C5): this used to embed the LIVE secrets in the clear — the
// engine's OFF_KEY, the webhook.site beacon token and the ntfy beacon topic —
// inside a Base64 blob that defeated every grep-based secret scan, in a PUBLIC
// repository. Those values are compromised and MUST BE ROTATED; deleting them
// here does not un-leak them, and they are deliberately not repeated in this
// comment for the same reason.
//
//   What is stored now is a template with {{...}} placeholders. The real values
//   are substituted from SERVER env at push time and never touch the repo. The
//   pin below covers the TEMPLATE (what is in version control); the rendered
//   notebook differs per deployment by design.
//
//   The substitution is byte-lossless: rendering the template with the original
//   values reproduces the original notebook exactly (sha256 3dc068d15a4c745d…),
//   so engine behaviour is unchanged by this refactor.
//
// USAGE (in the wake path):
//   import { getAetherNotebook } from "@/server/engine/aether-engine-source";
//   const text = getAetherNotebook(); // throws if tampered OR if a secret is unset
// ============================================================================

